using Asp.Versioning;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Servicio.RetazoMarket.Api.Extensions;using Servicio.RetazoMarket.Api.Models.Common;using Servicio.RetazoMarket.Business.DTOs.MovimientoProducto;using Servicio.RetazoMarket.Business.Exceptions;using Servicio.RetazoMarket.Business.Interfaces;using Servicio.RetazoMarket.DataManagment.Models.Common;
namespace Servicio.RetazoMarket.Api.Controllers.V1.Internal.Inventario;
[ApiController][ApiVersion("1.0")][Authorize(Policy=AuthorizationExtensions.AdministradorPolicy)][Route("api/v{version:apiVersion}/internal/inventario/movimientos-productos")][ProducesResponseType(typeof(ApiErrorResponse),400)][ProducesResponseType(typeof(ApiErrorResponse),401)][ProducesResponseType(typeof(ApiErrorResponse),403)][ProducesResponseType(typeof(ApiErrorResponse),404)]
public class MovimientosProductosController:ControllerBase{private readonly IMovimientoProductoService _s;public MovimientosProductosController(IMovimientoProductoService s)=>_s=s;
[HttpGet("{id:int}")]public async Task<IActionResult> PorId(int id,CancellationToken ct)=>Ok(ApiResponse<MovimientoProductoResponse>.Ok(await _s.ObtenerPorIdAsync(id,ct)??throw new NotFoundException("El movimiento no existe.")));
[HttpGet("producto/{id:int}")]public async Task<IActionResult> PorProducto(int id,CancellationToken ct)=>Ok(ApiResponse<IReadOnlyList<MovimientoProductoResponse>>.Ok(await _s.ObtenerPorProductoAsync(id,ct)));
[HttpGet("buscar")]public async Task<IActionResult> Buscar([FromQuery]MovimientoProductoFiltroRequest f,CancellationToken ct)=>Ok(ApiResponse<DataPagedResult<MovimientoProductoResponse>>.Ok(await _s.BuscarAsync(f,ct)));
[HttpPost]public async Task<IActionResult> Crear([FromBody]CrearMovimientoProductoRequest r,CancellationToken ct){var x=await _s.CrearAsync(r,ct);return CreatedAtAction(nameof(PorId),new{version="1.0",id=x.id_movimiento2},ApiResponse<MovimientoProductoResponse>.Ok(x,"Movimiento registrado exitosamente."));}}
